USE [JamunaBankProcurement];
GO
CREATE OR ALTER PROCEDURE dbo.usp_ProcurementTracking_Search @RequisitionNo VARCHAR(30)=NULL,@OrgUnitId BIGINT=NULL,@AssetId BIGINT=NULL,@StatusCode VARCHAR(40)=NULL,@ReferenceNo VARCHAR(100)=NULL AS BEGIN SET NOCOUNT ON; SELECT DISTINCT p.PROCUREMENT_ID,h.REQUISITION_ID,h.REQUISITION_NO,o.ORG_UNIT_NAME,s.STATUS_CODE,s.STATUS_NAME,p.PROCUREMENT_REFERENCE_NO,p.EXPECTED_COMPLETION_DATE,p.MODIFIED_DATE FROM dbo.PROCUREMENT_TRACKING p JOIN dbo.REQUISITION_HEADER h ON h.REQUISITION_ID=p.REQUISITION_ID JOIN dbo.ORG_UNIT o ON o.ORG_UNIT_ID=h.REQUESTED_ORG_UNIT_ID JOIN dbo.PROCUREMENT_STATUS_MASTER s ON s.STATUS_ID=p.CURRENT_STATUS_ID JOIN dbo.REQUISITION_ITEM i ON i.REQUISITION_ID=h.REQUISITION_ID AND i.IS_ACTIVE=1 WHERE (@RequisitionNo IS NULL OR h.REQUISITION_NO LIKE @RequisitionNo+'%') AND (@OrgUnitId IS NULL OR h.REQUESTED_ORG_UNIT_ID=@OrgUnitId) AND (@AssetId IS NULL OR i.ASSET_ID=@AssetId) AND (@StatusCode IS NULL OR s.STATUS_CODE=@StatusCode) AND (@ReferenceNo IS NULL OR p.PROCUREMENT_REFERENCE_NO=@ReferenceNo) ORDER BY p.MODIFIED_DATE DESC; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ProcurementTracking_UpdateStatus @RequisitionId BIGINT,@StatusCode VARCHAR(40),@ActorEmployeeId VARCHAR(30),@ReferenceNo VARCHAR(100)=NULL,@ExpectedCompletionDate DATE=NULL,@Remarks NVARCHAR(2000)=NULL,@BatchReferenceId UNIQUEIDENTIFIER=NULL
AS BEGIN SET NOCOUNT ON; SET XACT_ABORT ON; BEGIN TRY BEGIN TRAN; DECLARE @pid BIGINT,@sid BIGINT; SELECT @pid=PROCUREMENT_ID FROM dbo.PROCUREMENT_TRACKING WITH(UPDLOCK,HOLDLOCK) WHERE REQUISITION_ID=@RequisitionId; SELECT @sid=STATUS_ID FROM dbo.PROCUREMENT_STATUS_MASTER WHERE STATUS_CODE=@StatusCode AND IS_ACTIVE=1; IF @pid IS NULL OR @sid IS NULL THROW 51001,'Tracking or status not found.',1; UPDATE dbo.PROCUREMENT_TRACKING SET CURRENT_STATUS_ID=@sid,PROCUREMENT_REFERENCE_NO=COALESCE(@ReferenceNo,PROCUREMENT_REFERENCE_NO),EXPECTED_COMPLETION_DATE=COALESCE(@ExpectedCompletionDate,EXPECTED_COMPLETION_DATE),REMARKS=@Remarks,MODIFIED_DATE=SYSUTCDATETIME() WHERE PROCUREMENT_ID=@pid; INSERT dbo.PROCUREMENT_STATUS_HISTORY(PROCUREMENT_ID,STATUS_ID,REFERENCE_NO,CHANGED_BY_EMPLOYEE_ID,REMARKS,BATCH_REFERENCE_ID) VALUES(@pid,@sid,@ReferenceNo,@ActorEmployeeId,@Remarks,@BatchReferenceId); UPDATE dbo.REQUISITION_HEADER SET CURRENT_STATUS=CASE WHEN @StatusCode='PROCUREMENT_COMPLETED' THEN 'COMPLETED' ELSE 'PROCUREMENT_IN_PROGRESS' END,MODIFIED_BY=@ActorEmployeeId,MODIFIED_DATE=SYSUTCDATETIME() WHERE REQUISITION_ID=@RequisitionId; COMMIT; SELECT '000' RESULT_CODE,N'Success' RESULT_MESSAGE,@pid ENTITY_ID,@ReferenceNo REFERENCE_NO; END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; SELECT CASE WHEN ERROR_NUMBER()=51001 THEN '002' ELSE '999' END RESULT_CODE,ERROR_MESSAGE() RESULT_MESSAGE,NULL ENTITY_ID,@ReferenceNo REFERENCE_NO; END CATCH END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ProcurementTracking_GetHistory @RequisitionId BIGINT AS BEGIN SET NOCOUNT ON; SELECT h.*,s.STATUS_CODE,s.STATUS_NAME FROM dbo.PROCUREMENT_STATUS_HISTORY h JOIN dbo.PROCUREMENT_TRACKING p ON p.PROCUREMENT_ID=h.PROCUREMENT_ID JOIN dbo.PROCUREMENT_STATUS_MASTER s ON s.STATUS_ID=h.STATUS_ID WHERE p.REQUISITION_ID=@RequisitionId ORDER BY h.STATUS_DATE,h.STATUS_HISTORY_ID; END;
GO
